CREATE DATABASE IF NOT EXISTS meiset_magazasi CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE meiset_magazasi;

-- Qeyd: sxem dəyişəndə bu fayl yenidən işlədilə bilər (CREATE ... IF NOT EXISTS).

CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NOT NULL, name VARCHAR(180) NOT NULL UNIQUE, description VARCHAR(500), price DECIMAL(10,2) NOT NULL, image_url TEXT, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, address VARCHAR(500) NOT NULL, note VARCHAR(500), total DECIMAL(12,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Yeni', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id INT NOT NULL, product_name VARCHAR(180) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, line_total DECIMAL(12,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id));


